1	import { NextResponse } from "next/server";
2	import { randomUUID } from "node:crypto";
3	import { db } from "@/lib/db";
4	import { checkRateLimit } from "@/lib/rate-limit";
5	import { trustedClientIp } from "@/app/api/_lib/client-ip";
6	import { currentUser } from "@/lib/auth";
7	import { parseUserAgent } from "@/lib/ua-parse";
8	
9	export const runtime = "nodejs";
10	
11	/**
12	 * Page-view capture endpoint. Called fire-and-forget by <VisitTracker/> mounted
13	 * in the marketing layout and the portal Shell. It records a single `Visit` row
14	 * and MUST NOT throw or block the caller — analytics is strictly best-effort.
15	 *
16	 * The client IP is the PROXY-ATTESTED address (`trustedClientIp`); we never
17	 * trust a body-supplied IP, nor the first hop of `X-Forwarded-For` — nginx
18	 * appends to that header, so its first entry is caller-chosen. That mattered
19	 * twice here: it was the rate-limit key (so one header defeated the 60/min cap
20	 * on durable row insertion), and it is PERSISTED to `Visit.ip`, which is what
21	 * the admin visitors/analytics pages attribute traffic and abuse to. A forged
22	 * value poisoned both.
23	 *
24	 * Bots are dropped by a coarse UA check. The visit "kind" (marketing vs portal)
25	 * comes from a `?k=` query param the mounter sets.
26	 *
27	 * Two shapes of POST arrive here:
28	 *  - a PAGEVIEW (has `path`): inserts the Visit row, attaches session/pvid/utm and
29	 *    a stable, consent-gated `visitorId` (see below).
30	 *  - a CLOSE beacon (`{ close, pvid, dur }`, often via navigator.sendBeacon on
31	 *    pagehide): stamps the dwell time onto the earlier row with that pvid. This is
32	 *    what makes "avg time on site" and bounce rate possible.
33	 *
34	 * Stable visitor id (recurring vs new): we keep a first-party `nx_vid` cookie and
35	 * persist it on each Visit, so a returning person is recognisable across sessions
36	 * without any third party. It is CONSENT-GATED to the site's own opt-out model
37	 * (lib/consent.ts): only minted/persisted unless the visitor explicitly chose
38	 * "necessary" (nxeon_cookie_consent=necessary), in which case visitorId stays null
39	 * and that person is only ever counted by the coarse IP path.
40	 */
41	
42	const BOT_RE =
43	  /bot|crawl|spider|slurp|bingpreview|mediapartners|adsbot|facebookexternalhit|embedly|quora|pinterest|redditbot|whatsapp|telegrambot|discordbot|slackbot|semrush|ahrefs|mj12|dotbot|petalbot|yandex|baidu|duckduckbot|headless|phantomjs|python-requests|python-urllib|go-http|libwww|curl\/|wget\/|okhttp|axios\/|node-fetch|lighthouse|pagespeed|gtmetrix|pingdom|uptimerobot|statuscake|monitor|preview|scrapy/i;
44	
45	const VID_COOKIE = "nx_vid";
46	const VID_MAX_AGE = 60 * 60 * 24 * 365; // 1 year
47	const CONSENT_COOKIE = "nxeon_cookie_consent";
48	
49	/** Read one cookie value out of the raw Cookie header. */
50	function readCookie(req: Request, name: string): string | null {
51	  const raw = req.headers.get("cookie");
52	  if (!raw) return null;
53	  for (const part of raw.split("; ")) {
54	    if (part.startsWith(`${name}=`)) return part.slice(name.length + 1);
55	  }
56	  return null;
57	}
58	
59	/** Clamp a client-supplied opaque id to something sane before it hits the DB. */
60	function cleanId(v: unknown): string | null {
61	  if (typeof v !== "string") return null;
62	  const s = v.trim();
63	  if (!s || s.length > 64 || !/^[A-Za-z0-9._-]+$/.test(s)) return null;
64	  return s;
65	}
66	
67	function cleanUtm(v: unknown): string | null {
68	  if (typeof v !== "string") return null;
69	  const s = v.trim().slice(0, 120);
70	  return s || null;
71	}
72	
73	export async function POST(req: Request) {
74	  try {
75	    // Unauthenticated endpoint that writes a durable row per hit — throttle
76	    // per-IP to cap unbounded row insertion. Over the limit: silent no-op.
77	    const ip = trustedClientIp(req);
78	    const rl = checkRateLimit(`track:${ip}`, { max: 120, windowMs: 60_000 });
79	    if (!rl.ok) {
80	      return new NextResponse(null, { status: 204 });
81	    }
82	
83	    const url = new URL(req.url);
84	    const kindParam = url.searchParams.get("k");
85	    const kind = kindParam === "portal" ? "portal" : "marketing";
86	
87	    const body = (await req.json().catch(() => ({}))) as {
88	      path?: unknown;
89	      referrer?: unknown;
90	      sessionId?: unknown;
91	      pvid?: unknown;
92	      isEntry?: unknown;
93	      utmSource?: unknown;
94	      utmMedium?: unknown;
95	      utmCampaign?: unknown;
96	      gclid?: unknown;
97	      close?: unknown;
98	      dur?: unknown;
99	    };
100	
101	    // --- CLOSE beacon: attach dwell time to the earlier pageview row ---
102	    if (body.close === true) {
103	      const pvid = cleanId(body.pvid);
104	      const durRaw = typeof body.dur === "number" ? body.dur : Number(body.dur);
105	      if (pvid && Number.isFinite(durRaw)) {
106	        // Cap at 30 min so a backgrounded tab can't record an absurd dwell.
107	        const durationMs = Math.min(Math.max(Math.round(durRaw), 0), 30 * 60_000);
108	        await db.visit.updateMany({ where: { pvid }, data: { durationMs } });
109	      }
110	      return NextResponse.json({ ok: true });
111	    }
112	
113	    const ua = (req.headers.get("user-agent") ?? "").slice(0, 400);
114	    // Silently accept but skip obvious bots and empty UAs.
115	    if (!ua || BOT_RE.test(ua)) {
116	      return NextResponse.json({ ok: true });
117	    }
118	    const { deviceType, os, browser } = parseUserAgent(ua);
119	
120	    const path =
121	      typeof body.path === "string" && body.path ? body.path.slice(0, 300) : "/";
122	    let referrer =
123	      typeof body.referrer === "string" && body.referrer
124	        ? body.referrer.slice(0, 400)
125	        : null;
126	    // Drop same-origin referrers — they're just internal navigation noise.
127	    if (referrer) {
128	      try {
129	        if (new URL(referrer).host === url.host) referrer = null;
130	      } catch {
131	        /* keep opaque referrer strings as-is */
132	      }
133	    }
134	
135	    // --- Stable, consent-gated visitor id ---
136	    // Opt-out model mirrors lib/consent.ts marketingAllowed(): allowed unless the
137	    // visitor EXPLICITLY chose "necessary". No cookie is minted for an opted-out
138	    // person, so they carry no durable id.
139	    const consent = readCookie(req, CONSENT_COOKIE);
140	    const idAllowed = consent !== "necessary";
141	    let visitorId: string | null = null;
142	    let setVidCookie: string | null = null;
143	    if (idAllowed) {
144	      const existing = readCookie(req, VID_COOKIE);
145	      visitorId = existing && /^[A-Za-z0-9-]{8,64}$/.test(existing) ? existing : randomUUID();
146	      if (!existing) setVidCookie = visitorId;
147	    }
148	
149	    // --- Attribute the signed-in account (THE fix) ---
150	    // This is a POST from the browser, so the auth cookie rides along and
151	    // `currentUser()` resolves the same account the portal sees. Attaching the
152	    // userId is what lets the client profile show that person's OWN page history
153	    // and their location (portal visits especially). Anonymous marketing traffic
154	    // resolves to null and is unaffected. Wrapped so an auth hiccup never blocks
155	    // best-effort capture.
156	    let userId: string | null = null;
157	    try {
158	      userId = (await currentUser())?.id ?? null;
159	    } catch {
160	      /* auth resolution is best-effort; a failure just leaves the visit anon */
161	    }
162	
163	    // --- Google Ads click id (gclid) ---
164	    // Auto-tagging appends `?gclid=…` with NO utm_source, so without this the click
165	    // lands unattributed and buckets as "(none)". When we have a gclid but the
166	    // campaign set no explicit utm_source, label the source google/cpc so Google Ads
167	    // traffic shows up in the utmSource breakdown; never override an explicit utm.
168	    const gclid =
169	      typeof body.gclid === "string" && body.gclid
170	        ? body.gclid.replace(/[^A-Za-z0-9_-]/g, "").slice(0, 200) || null
171	        : null;
172	    let utmSource = cleanUtm(body.utmSource);
173	    let utmMedium = cleanUtm(body.utmMedium);
174	    if (gclid && !utmSource) {
175	      utmSource = "google";
176	      utmMedium = utmMedium ?? "cpc";
177	    }
178	
179	    await db.visit.create({
180	      data: {
181	        ip,
182	        path,
183	        referrer,
184	        ua,
185	        deviceType,
186	        os,
187	        browser,
188	        kind,
189	        userId,
190	        visitorId,
191	        sessionId: cleanId(body.sessionId),
192	        pvid: cleanId(body.pvid),
193	        isEntry: body.isEntry === true,
194	        utmSource,
195	        utmMedium,
196	        utmCampaign: cleanUtm(body.utmCampaign),
197	        gclid,
198	      },
199	    });
200	
201	    const res = NextResponse.json({ ok: true });
202	    if (setVidCookie) {
203	      res.cookies.set(VID_COOKIE, setVidCookie, {
204	        httpOnly: true,
205	        sameSite: "lax",
206	        secure: true,
207	        path: "/",
208	        maxAge: VID_MAX_AGE,
209	      });
210	    }
211	    return res;
212	  } catch {
213	    // Never surface capture failures to the page.
214	  }
215	  return NextResponse.json({ ok: true });
216	}
217

1	import { NextResponse } from "next/server";
2	import { checkRateLimit } from "@/lib/rate-limit";
3	import { trustedClientIp } from "@/app/api/_lib/client-ip";
4	import { currentUser } from "@/lib/auth";
5	import { insertDeployFunnelEvent } from "@/lib/deploy-funnel";
6	
7	export const runtime = "nodejs";
8	
9	/**
10	 * Deploy-funnel event sink. Called fire-and-forget by the customer deploy wizards
11	 * (components/customer/*DeployWizard.tsx) as a person moves through the steps, and
12	 * by the same wizards when a step throws / a provision call fails. Server-side
13	 * provisioning failures are recorded via `recordDeployFunnelError` (lib/deploy-funnel.ts)
14	 * rather than this HTTP path.
15	 *
16	 * Records one `DeployFunnelEvent`. Like /api/track it MUST NOT throw or block —
17	 * analytics is strictly best-effort. It attributes the signed-in account via
18	 * `currentUser()` (the auth cookie rides the POST) and the stable visitor cookie,
19	 * so an admin can later tie a stuck/errored session back to a real customer.
20	 */
21	
22	const VID_COOKIE = "nx_vid";
23	const PRODUCTS = new Set(["vps", "game", "hosting", "email"]);
24	const TYPES = new Set(["step", "error", "complete"]);
25	
26	function readCookie(req: Request, name: string): string | null {
27	  const raw = req.headers.get("cookie");
28	  if (!raw) return null;
29	  for (const part of raw.split("; ")) {
30	    if (part.startsWith(`${name}=`)) return part.slice(name.length + 1);
31	  }
32	  return null;
33	}
34	
35	function cleanId(v: unknown): string | null {
36	  if (typeof v !== "string") return null;
37	  const s = v.trim();
38	  if (!s || s.length > 64 || !/^[A-Za-z0-9._-]+$/.test(s)) return null;
39	  return s;
40	}
41	
42	function cleanStr(v: unknown, max: number): string | null {
43	  if (typeof v !== "string") return null;
44	  const s = v.trim().slice(0, max);
45	  return s || null;
46	}
47	
48	export async function POST(req: Request) {
49	  try {
50	    const ip = trustedClientIp(req);
51	    const rl = checkRateLimit(`deploystep:${ip}`, { max: 120, windowMs: 60_000 });
52	    if (!rl.ok) return new NextResponse(null, { status: 204 });
53	
54	    const body = (await req.json().catch(() => ({}))) as Record<string, unknown>;
55	
56	    const product = typeof body.product === "string" ? body.product : "";
57	    if (!PRODUCTS.has(product)) return NextResponse.json({ ok: true });
58	    const step = cleanStr(body.step, 60);
59	    if (!step) return NextResponse.json({ ok: true });
60	    const stepIndexRaw = typeof body.stepIndex === "number" ? body.stepIndex : Number(body.stepIndex);
61	    const stepIndex = Number.isFinite(stepIndexRaw) ? Math.max(0, Math.min(50, Math.round(stepIndexRaw))) : 0;
62	    const type = typeof body.type === "string" && TYPES.has(body.type) ? body.type : "step";
63	
64	    let userId: string | null = null;
65	    try {
66	      userId = (await currentUser())?.id ?? null;
67	    } catch {
