1	import { NextResponse } from "next/server";
2	import { db } from "@/lib/db";
3	
4	// 1x1 transparent GIF — the smallest valid image, so the "load" completes
5	// instantly and never renders anything visible even if an unusually permissive
6	// mail client shows broken-image alt text otherwise.
7	const PIXEL = Buffer.from("R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBTAA7", "base64");
8	
9	const PIXEL_HEADERS = {
10	  "Content-Type": "image/gif",
11	  "Content-Length": String(PIXEL.length),
12	  // Never cached — a mail client (or its image proxy) caching this would
13	  // silently stop pinging us on repeat opens.
14	  "Cache-Control": "no-store, no-cache, must-revalidate, private",
15	  Pragma: "no-cache",
16	};
17	
18	/**
19	 * Email open-tracking pixel. GET-only, unauthenticated by necessity — mail
20	 * clients fetch `<img>` tags with no credentials of any kind. Always returns
21	 * the pixel even when the DB update fails or `id` doesn't match any row: a
22	 * tracking miss must never look like a broken image to the recipient.
23	 */
24	export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
25	  const { id } = await params;
26	  try {
27	    await db.emailLog.updateMany({
28	      where: { id },
29	      data: { openCount: { increment: 1 } },
30	    });
31	    // Separate call so `openedAt` is set only on the FIRST open (a raw
32	    // increment has no "only if null" form) — cheap given how rarely a given
33	    // pixel is hit at all, let alone twice in the same instant.
34	    await db.emailLog.updateMany({
35	      where: { id, openedAt: null },
36	      data: { openedAt: new Date() },
37	    });
38	  } catch {
39	    // Best-effort — the pixel must render regardless.
40	  }
41	  return new NextResponse(PIXEL, { headers: PIXEL_HEADERS });
42	}
