5	/**
6	 * Email click-tracking redirect. GET-only, unauthenticated by necessity (the
7	 * recipient is clicking from their mail client, not a logged-in browser tab).
8	 *
9	 * `idx` is a positional index into the EmailLog row's own `links` array —
10	 * NEVER a client-supplied URL. lib/mailer.ts populates that array at send
11	 * time from the email's own real anchors (minus anything secret-bearing), so
12	 * this route can only ever redirect somewhere WE put in that specific email.
13	 * That is a deliberate design choice, not an oversight: a click endpoint that
14	 * instead took `?u=<url>` would be a textbook open redirect — usable to
15	 * launder an arbitrary destination behind a trusted nxeon.cloud link.
16	 */
17	export async function GET(
18	  _req: Request,
19	  { params }: { params: Promise<{ id: string; idx: string }> },
20	) {
21	  const { id, idx } = await params;
22	  const i = Number(idx);
23	  const fallback = NextResponse.redirect(appUrl(), 302);
24	
25	  if (!Number.isInteger(i) || i < 0) return fallback;
26	
27	  try {
28	    const row = await db.emailLog.findUnique({ where: { id }, select: { links: true } });
29	    const links = Array.isArray(row?.links) ? (row.links as unknown[]) : null;
30	    const target = links && typeof links[i] === "string" ? (links[i] as string) : null;
31	    if (!target) return fallback;
32	
33	    await db.emailLog.updateMany({
34	      where: { id },
35	      data: { clickCount: { increment: 1 } },
36	    });
37	    await db.emailLog.updateMany({
38	      where: { id, clickedAt: null },
39	      data: { clickedAt: new Date() },
40	    });
41	
42	    return NextResponse.redirect(target, 302);
43	  } catch {
44	    return fallback;
45	  }
46	}
