1	import { NextRequest, NextResponse } from "next/server";
2	import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
3	import { checkRateLimit } from "@/lib/rate-limit";
4	import { ingestTelemetryBatch, type BatchIn } from "@/lib/telemetry";
5	
6	export const runtime = "nodejs";
7	export const dynamic = "force-dynamic";
8	
9	/**
10	 * POST /api/telemetry/ingest — receives a batched-events payload from the
11	 * nxeon-shipper agent (see agent/nxeon-shipper/main.go `sender()`), running
12	 * either per-server on a VPS/game box or once centrally on a shared-hosting
13	 * or mail node.
14	 *
15	 * AUTH: `Authorization: Bearer <token>` — a persistent, hash-at-rest token
16	 * minted at provision time (lib/telemetry-token.ts), NOT the session-cookie
17	 * auth every other API route in this app uses. This endpoint is reachable
18	 * from customer VMs on the public internet, not just the admin's browser.
19	 *
20	 * This intentionally does the least amount of work possible per request:
21	 * validate the token, clamp + insert the batch, return. No fan-out, no
22	 * websocket push here — the admin monitor page reads back via its existing
23	 * poll (see lib/telemetry.ts header comment for why that's the right call
24	 * on a single-node deployment).
25	 */
26	export async function POST(req: NextRequest) {
27	  const auth = req.headers.get("authorization") ?? "";
28	  const token = auth.startsWith("Bearer ") ? auth.slice(7).trim() : "";
29	  if (!token) {
30	    return NextResponse.json({ error: "unauthorized" }, { status: 401, headers: NO_STORE_HEADERS });
31	  }
32	
33	  // Throttle per-token rather than per-IP: a shipper on a NATted VM shares an
34	  // IP with the platform's own NAT gateway, but always presents its own
35	  // token, so this is the correct dedup key. Generous ceiling — a legitimate
36	  // shipper posts ~1 batch/3s; this allows bursts (e.g. reconnect after an
37	  // outage flushing several catch-up batches) without false-positiving.
38	  const rl = checkRateLimit(`telemetry:ingest:${token}`, { max: 40, windowMs: 60_000 });
39	  if (!rl.ok) {
40	    return NextResponse.json({ error: "rate limited" }, { status: 429, headers: NO_STORE_HEADERS });
41	  }
42	
43	  let body: BatchIn;
44	  try {
45	    body = await req.json();
46	  } catch {
47	    return NextResponse.json({ error: "invalid json" }, { status: 400, headers: NO_STORE_HEADERS });
48	  }
49	
50	  try {
51	    const result = await ingestTelemetryBatch(token, body);
52	    if (!result.ok) {
53	      return NextResponse.json({ error: result.reason }, { status: 401, headers: NO_STORE_HEADERS });
54	    }
55	    return NextResponse.json({ ok: true, stored: result.stored }, { headers: NO_STORE_HEADERS });
56	  } catch (e) {
57	    console.error("[telemetry/ingest] route error", e);
58	    return NextResponse.json({ error: "ingest failed" }, { status: 500, headers: NO_STORE_HEADERS });
59	  }
60	}
