1	/**
2	 * Live-telemetry ingestion + read-back for the nxeon-shipper agent feature.
3	 *
4	 * WHAT THIS IS: a short rolling window (TELEMETRY_RETENTION_HOURS) of raw
5	 * connection/auth events shipped by nxeon-shipper — SSH logins/logouts/failed
6	 * attempts, visitor HTTP hits, and mail auth attempts — fanned into the same
7	 * /admin/monitor page the existing Live Ops feed (lib/monitor-feed.ts) drives.
8	 *
9	 * ARCHITECTURE CALL (documented per the task's "make the reasonable call"
10	 * instruction): this is DB-backed (a `TelemetryEvent` row per event), read by
11	 * the existing 8s poll in LiveMonitorTerminal, NOT a new SSE/WebSocket
12	 * channel. Reasons:
13	 *   1. Single-node deployment (see docs/DOCUMENTATION.md) — there is exactly
14	 *      one Next.js process and one worker process; a push channel would only
15	 *      be saving the latency of one indexed, limit-50 query every 8s, which
16	 *      is not meaningfully "not live" for an ops console (SSH events show up
17	 *      within one poll tick, i.e. worst-case ~8s, typically 2-5s given the
18	 *      shipper's own 3s batch interval).
19	 *   2. The existing monitor page is ALREADY a poll loop end to end (route +
20	 *      component); adding a second transport (SSE) alongside it for only
21	 *      SOME event types would fragment the one console into two update
22	 *      cadences for no operator-visible benefit, and every other admin
23	 *      surface in this codebase (Jobs, HostingTask, node stats) is polled
24	 *      the same way.
25	 *   3. Postgres growth is bounded by retention (below) + the worker sweep
26	 *      (worker/telemetry.ts telemetrySweep), so "DB as ring buffer" carries
27	 *      none of the unbounded-growth risk that would make this a bad idea.
28	 * If a future phase needs sub-second delivery (e.g. a live "who's SSH'd in
29	 * right now" indicator), promote just that slice to SSE — terminal-server's
30	 * `ws` dependency is already in the tree as prior art for a push channel.
31	 */
32	import { db } from "./db";
33	import { resolveTelemetryPrincipal } from "./telemetry-token";
34	
35	export const TELEMETRY_RETENTION_HOURS = 48;
36	/** Hard cap on events accepted per batch POST — matches the shipper's own
37	 *  batchMaxEvents (50) with headroom, so a misbehaving/compromised agent
38	 *  can't smuggle an oversized payload through one request. */
39	const MAX_EVENTS_PER_BATCH = 200;
40	const VALID_TYPES = new Set(["SSH_LOGIN", "SSH_LOGOUT", "SSH_FAILED", "VISITOR", "MAIL_AUTH"]);
41	const VALID_NODE_KINDS = new Set(["VPS", "GAME", "HOSTING", "MAIL"]);
42	
43	export type EventIn = {
44	  type: string;
45	  ts: string;
46	  ip?: string;
47	  user?: string;
48	  path?: string;
49	  status?: string;
50	  meta?: string;
51	  site?: string;
52	};
53	
54	export type BatchIn = {
55	  server_id?: string;
56	  node_kind?: string;
57	  label?: string;
58	  events?: EventIn[];
59	};
60	
61	export function clip(s: string | undefined | null, max: number): string | undefined {
62	  if (!s) return undefined;
63	  return s.length > max ? s.slice(0, max) : s;
64	}
65	
66	/**
67	 * Pure batch → row-shape transform, split out from ingestTelemetryBatch so it
68	 * can be unit-tested without a database (see test/telemetry.test.ts) — same
69	 * "extract the pure function" pattern worker/provision-health.ts's
70	 * attemptsFor/retryCheck use. Clamps batch size, drops malformed/unknown
71	 * event types, and clips every free-form string field so one hostile/buggy
72	 * shipper can't smuggle an oversized row into Postgres.
73	 */
74	export function buildTelemetryRows(principal: import("./telemetry-token").TelemetryPrincipal, body: BatchIn) {
75	  const events = Array.isArray(body.events) ? body.events.slice(0, MAX_EVENTS_PER_BATCH) : [];
76	  const label = clip(body.label, 200) ?? null;
77	  return events
78	    .filter((e) => e && typeof e.type === "string" && VALID_TYPES.has(e.type))
79	    .map((e) => {
80	      let ts = new Date(e.ts);
81	      if (Number.isNaN(ts.getTime())) ts = new Date();
82	      return {
83	        serverId: principal.kind === "VPS" || principal.kind === "GAME" ? principal.serverId : null,
84	        nodeId: principal.kind === "HOSTING" ? principal.nodeId : principal.kind === "MAIL" ? "mail" : null,
85	        nodeKind: principal.kind,
86	        type: e.type,
87	        ts,
88	        ip: clip(e.ip, 64) ?? null,
89	        user: clip(e.user, 128) ?? null,
90	        path: clip(e.path, 512) ?? null,
91	        site: clip(e.site, 200) ?? null,
92	        status: clip(e.status, 32) ?? null,
93	        meta: clip(e.meta, 256) ?? null,
94	        label,
95	      };
96	    });
97	}
98	
99	/**
100	 * Validate the bearer token against Server/HostingNode/mail-secret, validate
101	 * + clamp the batch shape, and insert. Returns the count actually stored (0
102	 * if the token was invalid or the batch was empty/malformed — callers should
103	 * still answer 401 for a bad token, this function only owns the DB write).
104	 */
105	export async function ingestTelemetryBatch(
106	  token: string,
107	  body: BatchIn
108	): Promise<{ ok: true; stored: number } | { ok: false; reason: string }> {
109	  const nodeKind = body.node_kind && VALID_NODE_KINDS.has(body.node_kind) ? body.node_kind : "VPS";
110	  const principal = await resolveTelemetryPrincipal(token, nodeKind);
111	  if (!principal) return { ok: false, reason: "invalid token" };
112	
113	  const rows = buildTelemetryRows(principal, body);
114	  if (rows.length === 0) return { ok: true, stored: 0 };
115	
116	  await db.telemetryEvent.createMany({ data: rows });
117	  return { ok: true, stored: rows.length };
118	}
119	
120	export type TelemetryEventView = {
121	  id: string;
122	  serverId: string | null;
123	  nodeId: string | null;
124	  nodeKind: string;
125	  type: string;
126	  ts: string;
127	  ip: string | null;
128	  user: string | null;
129	  path: string | null;
130	  site: string | null;
131	  status: string | null;
132	  meta: string | null;
133	  label: string | null;
134	};
135	
136	/**
137	 * Recent events for the admin monitor feed. Capped at `limit` (the monitor
138	 * UI only ever shows a scrolling tail, same as the existing Job/HostingTask
139	 * action log), ordered newest-first.
140	 */
141	export async function getRecentTelemetry(limit = 80): Promise<TelemetryEventView[]> {
142	  const rows = await db.telemetryEvent.findMany({
143	    orderBy: { createdAt: "desc" },
144	    take: limit,
145	  });
146	  return rows.map((r) => ({
147	    id: r.id,
148	    serverId: r.serverId,
149	    nodeId: r.nodeId,
150	    nodeKind: r.nodeKind,
151	    type: r.type,
152	    ts: r.ts.toISOString(),
153	    ip: r.ip,
154	    user: r.user,
155	    path: r.path,
156	    site: r.site,
157	    status: r.status,
158	    meta: r.meta,
159	    label: r.label,
160	  }));
161	}
162	
163	/**
164	 * Prune rows past the retention window. Called first (before anything that
165	 * could throw) by worker/telemetry.ts's sweep, same "prune, then act" order
166	 * as worker/monitor.ts sampleServerDisks — a prune failure must never block
167	 * the rest of the sweep, and the rest of the sweep must never leave stale
168	 * rows to expire only when a LATER sweep happens to succeed.
169	 */
170	export async function pruneTelemetry(): Promise<number> {
171	  const cutoff = new Date(Date.now() - TELEMETRY_RETENTION_HOURS * 60 * 60_000);
172	  const { count } = await db.telemetryEvent.deleteMany({ where: { createdAt: { lt: cutoff } } });
173	  return count;
174	}
