8	/**
9	 * Open-tracking pixel. Verifies the HMAC token, records an OPEN EmailEvent for the
10	 * send, and always returns a 1x1 transparent GIF (even on a bad token) so a broken
11	 * or replayed link never shows a broken-image icon in a recipient's inbox.
12	 *
13	 * Never throws, never blocks: a tracking write failing must not fail the pixel.
14	 */
15	
16	// 1x1 transparent GIF.
17	const PIXEL = Buffer.from("R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7", "base64");
18	
19	function gif(): Response {
20	  return new NextResponse(new Uint8Array(PIXEL), {
21	    status: 200,
22	    headers: {
23	      "Content-Type": "image/gif",
24	      "Content-Length": String(PIXEL.length),
25	      "Cache-Control": "no-store, no-cache, must-revalidate, private",
26	      Pragma: "no-cache",
27	    },
28	  });
29	}
