93	/**
94	 * Verify the token and record a GLOBAL suppression. Idempotent and silent about
95	 * whether the contact exists. Returns true when the request was well-formed.
96	 */
97	async function applyUnsubscribe(token: string | null): Promise<boolean> {
98	  const claims = verifyUnsubscribeToken(token);
99	  if (!claims) return false;
100	
101	  // Resolve the contact's email from the signed contactId. If the contact is
102	  // gone we still succeed (nothing to suppress, but the request was valid).
103	  const contact = await db.contact.findUnique({
104	    where: { id: claims.contactId },
105	    select: { email: true },
106	  });
107	  const email = (contact?.email ?? "").trim().toLowerCase();
108	  if (!email) return true;
109	
110	  // Idempotent: only insert if no GLOBAL row for this address exists yet.
111	  const existing = await db.suppression.findFirst({
112	    where: { email, scope: "GLOBAL" },
113	    select: { id: true },
114	  });
115	  if (!existing) {
116	    await db.suppression.create({
117	      data: { email, scope: "GLOBAL", reason: "UNSUBSCRIBE" },
118	    });
119	  }
120	  return true;
121	}
