131	export async function POST(req: Request) {
132	  // Token may arrive in the query string (RFC 8058 one-click) or the form body.
133	  let token = new URL(req.url).searchParams.get("token");
134	  if (!token) {
135	    try {
136	      const form = await req.formData();
137	      token = (form.get("token") as string | null) ?? null;
138	    } catch {
139	      /* no body */
140	    }
141	  }
142	
143	  const ok = await applyUnsubscribe(token);
144	  if (!ok) {
145	    return page("Invalid link", "This unsubscribe link is invalid or has expired.", 400);
146	  }
