4	/**
5	 * Tokenized, NO-LOGIN marketing unsubscribe.
6	 *
7	 * The token (a signed `<userId>.<hmac>` from lib/marketing-unsub, purpose-tagged
8	 * so it can't be repurposed) is the whole authorization — the recipient proves
9	 * intent by clicking the link we mailed them. Opting out is idempotent and writes
10	 * the same signal `mayDeliverTo(userId,'product_news','email')` reads, so future
11	 * marketing sends to this user are suppressed centrally by `sendMail`.
12	 *
13	 *   GET  → flip the opt-out and render a friendly confirmation page.
14	 *   POST → RFC 8058 one-click (mailbox providers): opt out, 200, no body.
15	 *
16	 * Runs on the Node.js runtime because the verifier uses node:crypto.
17	 */
18	export const runtime = "nodejs";
19	
20	async function applyOptOut(token: string | null): Promise<boolean> {
21	  const userId = verifyMarketingUnsubToken(token);
22	  if (!userId) return false;
23	  try {
24	    return await optOutMarketing(userId);
25	  } catch (e) {
26	    console.error("[unsubscribe] opt-out failed", e);
27	    return false;
28	  }
29	}
