1	import { NextResponse } from "next/server";
2	import { logError } from "@/lib/log";
3	import { checkRateLimit } from "@/lib/rate-limit";
4	import { trustedClientIp } from "@/app/api/_lib/client-ip";
5	
6	export const runtime = "nodejs";
7	
8	// Receives client-side error reports from the error boundaries. Payload is
9	// size-capped and never trusted beyond logging.
10	export async function POST(req: Request) {
11	  // Unauthenticated endpoint: throttle per-IP so it can't be used to amplify
12	  // the ops webhook or pin request slots. Silently no-op when over the limit.
13	  const ip = trustedClientIp(req);
14	  const rl = checkRateLimit(`log:${ip}`, { max: 20, windowMs: 60_000 });
15	  if (!rl.ok) {
16	    return new NextResponse(null, { status: 204 });
17	  }
18	
19	  try {
20	    const body = (await req.json().catch(() => ({}))) as {
21	      context?: string;
22	      message?: string;
23	      digest?: string;
24	      path?: string;
25	      stack?: string;
26	    };
27	    const clip = (s: unknown, n: number) => (typeof s === "string" ? s.slice(0, n) : undefined);
28	    // Fire-and-forget: the webhook fan-out in lib/log.ts awaits an outbound
29	    // fetch, so do NOT block the response on it. Errors are swallowed there.
30	    void logError(clip(body.context, 80) ?? "client-error", { message: clip(body.message, 500), digest: clip(body.digest, 80) }, {
31	      path: clip(body.path, 200),
32	      stack: clip(body.stack, 2000),
33	      source: "client",
34	    });
35	  } catch {
36	    // ignore malformed reports
37	  }
38	  return NextResponse.json({ ok: true });
39	}
