1	import { NextRequest, NextResponse } from "next/server";
2	import { db } from "@/lib/db";
3	import { currentUser } from "@/lib/auth";
4	import { vmRrd, nodeRrd, pveFor, pveForNode } from "@/lib/proxmox";
5	import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
6	
7	export const dynamic = "force-dynamic";
8	
9	export async function GET(req: NextRequest) {
10	  const user = await currentUser();
11	  if (!user) {
12	    return NextResponse.json({ error: "unauthorized" }, { status: 401, headers: NO_STORE_HEADERS });
13	  }
14	
15	  const timeframe = ["hour", "day", "week", "month"].includes(req.nextUrl.searchParams.get("tf") ?? "")
16	    ? req.nextUrl.searchParams.get("tf")!
17	    : "hour";
18	
19	  const serverId = req.nextUrl.searchParams.get("serverId");
20	  try {
21	    if (serverId) {
22	      const server = await db.server.findUnique({ where: { id: serverId }, include: { node: true } });
23	      if (!server || (server.userId !== user.id && user.role !== "ADMIN") || !server.vmid) {
24	        return NextResponse.json({ error: "not found" }, { status: 404, headers: NO_STORE_HEADERS });
25	      }
26	      // Query the node the VM actually lives on — vmids collide across nodes, so
27	      // defaulting to the primary would leak another tenant's same-numbered VM.
28	      const conn = server.node
29	        ? pveFor({
30	            apiUrl: server.node.apiUrl,
31	            pveNode: server.node.pveNode,
32	            tokenId: server.node.tokenId,
33	            tokenSecret: server.node.tokenSecret,
34	          })
35	        : undefined;
36	      const data = await vmRrd(server.vmid, timeframe, conn);
37	      return NextResponse.json({ data }, { headers: NO_STORE_HEADERS });
38	    }
39	    if (user.role !== "ADMIN") {
40	      return NextResponse.json({ error: "forbidden" }, { status: 403, headers: NO_STORE_HEADERS });
41	    }
42	    // Fleet-wide admin chart — was hardcoded to the primary node's env-derived
43	    // connection, which silently omitted every other node. Now selectable via
44	    // ?node=<id>, defaulting to the primary (or first enabled) node.
45	    const nodes = await db.node.findMany({
46	      where: { enabled: true },
47	      orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }],
48	    });
49	    const nodeParam = req.nextUrl.searchParams.get("node");
50	    const target = (nodeParam && nodes.find((n) => n.id === nodeParam)) || nodes[0];
51	    const conn = target ? pveForNode(target) : undefined;
52	    const data = await nodeRrd(timeframe, conn);
53	    return NextResponse.json(
54	      { data, nodes: nodes.map((n) => ({ id: n.id, name: n.name })), nodeId: target?.id ?? null },
55	      { headers: NO_STORE_HEADERS }
56	    );
57	  } catch {
58	    // An empty series is the SAME shape we return for a VM that genuinely has
59	    // no RRD data yet, so swallowing the error here told the customer "your
60	    // server reported nothing" when the truth was "we could not reach Proxmox
61	    // to ask". Keep the 200 + empty array (the chart handles it), but state
62	    // plainly that this is an unavailable upstream, not an observed silence.
63	    return NextResponse.json(
64	      { data: [], unavailable: true },
65	      { headers: NO_STORE_HEADERS },
66	    );
67	  }
68	}
