289	// ---------------------------------------------------------------------------
290	// Brand compliance readiness
291	// ---------------------------------------------------------------------------
292	
293	export type ComplianceRequirement = {
294	  key: "physicalPostalAddress" | "replyTo" | "fromEmail" | "verifiedDomain";
295	  label: string;
296	};
297	
298	/**
299	 * Which hard compliance requirements a brand is still missing. An empty array
300	 * means the brand is clear to preview/queue a campaign. Requirements:
301	 *  - a valid physical postal address (CAN-SPAM),
302	 *  - a reply-to address,
303	 *  - an honest From address,
304	 *  - a domain with SPF + DKIM + DMARC all verified (Gmail/Yahoo bulk rules).
305	 */
306	export function requireBrandCompliance(brand: BrandLike): ComplianceRequirement[] {
307	  const missing: ComplianceRequirement[] = [];
308	  if (!(brand.physicalPostalAddress ?? "").trim()) {
309	    missing.push({ key: "physicalPostalAddress", label: "Physical postal address (required by CAN-SPAM)" });
310	  }
311	  if (!(brand.replyTo ?? "").trim()) {
312	    missing.push({ key: "replyTo", label: "Reply-to address" });
313	  }
314	  if (!(brand.fromEmail ?? "").trim()) {
315	    missing.push({ key: "fromEmail", label: "From address" });
316	  }
317	  if (!(brand.spfVerified && brand.dkimVerified && brand.dmarcVerified)) {
318	    missing.push({ key: "verifiedDomain", label: "Verified sending domain (SPF + DKIM + DMARC)" });
319	  }
320	  return missing;
321	}
322	
323	/** Convenience: true when the brand has no outstanding compliance requirements. */
324	export function brandIsCompliant(brand: BrandLike): boolean {
325	  return requireBrandCompliance(brand).length === 0;
326	}
327	
328	// ---------------------------------------------------------------------------
329	// Reputation isolation — protected sending domains
330	// ---------------------------------------------------------------------------
331	
332	/**
333	 * Domains the cold-email engine must NEVER send from, no matter how a brand is
334	 * configured. These carry the platform's transactional + mailbox reputation, so a
335	 * cold campaign leaking onto them would put customer mail (receipts, password
336	 * resets, business mailboxes) at deliverability risk. Always includes the mail
337	 * host; callers merge in the app host + any operator-configured domains.
338	 */
339	export const ALWAYS_PROTECTED_DOMAINS: readonly string[] = ["nxeon.cloud", "mail.nxeon.cloud"];
340	
341	/** Lower-case, strip a leading protocol/@, and drop any path/port from a domain. */
342	export function normalizeDomain(value: string | null | undefined): string {
343	  let d = (value ?? "").trim().toLowerCase();
344	  if (!d) return "";
345	  const at = d.lastIndexOf("@");
346	  if (at !== -1) d = d.slice(at + 1);
347	  d = d.replace(/^https?:\/\//, "");
348	  d = d.split("/")[0].split(":")[0];
349	  return d.trim();
350	}
351	
352	/**
353	 * Build the full protected-domain set from the operator setting plus the
354	 * always-protected base and the app host. Deduped, normalised, no empties.
355	 */
356	export function protectedDomainSet(configured: string | null | undefined, appHost?: string | null): Set<string> {
357	  const out = new Set<string>();
358	  for (const d of ALWAYS_PROTECTED_DOMAINS) out.add(normalizeDomain(d));
359	  const host = normalizeDomain(appHost);
360	  if (host) out.add(host);
361	  for (const tok of (configured ?? "").split(/[\s,;]+/)) {
362	    const d = normalizeDomain(tok);
363	    if (d) out.add(d);
364	  }
365	  out.delete("");
366	  return out;
367	}
368	
369	/**
370	 * Is `domain` protected? Matches the exact domain AND any subdomain of a protected
371	 * apex (so `bulk.nxeon.cloud` is blocked when `nxeon.cloud` is protected).
372	 */
373	export function isProtectedDomain(domain: string | null | undefined, protectedSet: Set<string> | string[]): boolean {
374	  const d = normalizeDomain(domain);
375	  if (!d) return true; // no sending domain at all → refuse, never fail open
376	  const set = protectedSet instanceof Set ? protectedSet : new Set(protectedSet.map(normalizeDomain));
377	  if (set.has(d)) return true;
378	  for (const p of set) {
379	    if (p && d.endsWith(`.${p}`)) return true;
380	  }
381	  return false;
382	}
383	
384	export type SendEligibility = {
385	  eligible: boolean;
386	  reasons: string[];
387	  checks: { key: string; label: string; ok: boolean }[];
388	};
389	
390	/**
391	 * The full send-eligibility verdict for a brand: CAN-SPAM/DNS compliance
392	 * (requireBrandCompliance) PLUS reputation isolation (the From domain must not be
393	 * protected) PLUS the circuit-breaker pause flag. Returns a red/green checklist
394	 * for the UI and a machine-usable `eligible`. This is the single gate the worker
395	 * and the Launch action both consult, so they can never disagree.
396	 */
397	export function evaluateSendEligibility(
398	  brand: BrandLike & {
399	    fromEmail?: string | null;
400	    sendingDomain?: string | null;
401	    sendingPaused?: boolean;
402	    pausedReason?: string | null;
403	  },
404	  protectedSet: Set<string> | string[],
405	): SendEligibility {
406	  const missing = requireBrandCompliance(brand);
407	  const complianceOk = missing.length === 0;
408	
409	  const fromDomain = normalizeDomain(brand.sendingDomain) || normalizeDomain(brand.fromEmail);
410	  const notProtected = !isProtectedDomain(fromDomain, protectedSet);
411	  const hasFromDomain = !!fromDomain;
412	  const notPaused = !brand.sendingPaused;
413	
414	  const checks = [
415	    { key: "address", label: "Physical postal address", ok: !!(brand.physicalPostalAddress ?? "").trim() },
416	    {
417	      key: "dns",
418	      label: "SPF + DKIM + DMARC verified",
419	      ok: !!(brand.spfVerified && brand.dkimVerified && brand.dmarcVerified),
420	    },
421	    { key: "dedicatedDomain", label: "Dedicated sending domain set", ok: hasFromDomain },
422	    { key: "notProtected", label: "Not a protected/platform domain", ok: hasFromDomain && notProtected },
423	    { key: "notPaused", label: "Not paused by the circuit breaker", ok: notPaused },
424	  ];
425	
426	  const reasons: string[] = [];
427	  for (const m of missing) reasons.push(m.label);
428	  if (!hasFromDomain) reasons.push("No dedicated sending domain configured");
429	  else if (!notProtected) {
430	    reasons.push(
431	      `Sending domain "${fromDomain}" is a protected platform domain — cold email must use a dedicated domain`,
432	    );
433	  }
434	  if (!notPaused) reasons.push(`Sending is paused${brand.pausedReason ? `: ${brand.pausedReason}` : ""}`);
435	
436	  return {
437	    eligible: complianceOk && hasFromDomain && notProtected && notPaused,
438	    reasons,
439	    checks,
440	  };
441	}
442	
443	// ---------------------------------------------------------------------------
444	// Mandatory message footer
445	// ---------------------------------------------------------------------------
446	
447	/**
448	 * The compliance footer that every message must carry: the sender's physical
449	 * postal address (CAN-SPAM) plus a one-click unsubscribe line (RFC 8058 /
450	 * Gmail-Yahoo). Plain text — the template layer wraps it for HTML.
451	 */
452	export function complianceFooter(brand: BrandLike, unsubscribeUrl: string): string {
453	  const address = (brand.physicalPostalAddress ?? "").trim() || "[physical postal address not set]";
454	  return [
455	    "You are receiving this message as a business contact.",
456	    `Our postal address: ${address}`,
457	    `To stop receiving these emails, unsubscribe here: ${unsubscribeUrl}`,
458	  ].join("\n");
459	}
