1	import { NextRequest, NextResponse } from "next/server";
2	import { currentUser } from "@/lib/auth";
3	import { db } from "@/lib/db";
4	import { invoiceBranding, renderInvoiceHTML } from "@/lib/invoices";
5	
6	/**
7	 * Returns the branded, print-ready invoice as standalone HTML.
8	 *
9	 * NOTE: There is no PDF library installed and we cannot add dependencies, so
10	 * this is the pragmatic approach — the page ships with a print-optimised
11	 * stylesheet and a "Print / Save as PDF" button; the browser's Print → Save
12	 * as PDF produces the downloadable document.
13	 */
14	export async function GET(_req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
15	  const { id } = await params;
16	  const user = await currentUser();
17	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
18	
19	  const invoice = await db.invoice.findUnique({
20	    where: { id },
21	    include: { user: { select: { name: true, email: true } } },
22	  });
23	  if (!invoice) return NextResponse.json({ error: "not found" }, { status: 404 });
24	
25	  const isOwner = invoice.userId === user.id;
26	  const isAdmin = user.role === "ADMIN";
27	  if (!isOwner && !isAdmin) {
28	    return NextResponse.json({ error: "forbidden" }, { status: 403 });
29	  }
30	
31	  // The downloaded document must carry the same identifier the dashboard showed the
