11	/**
12	 * Streams the invoice as a REAL, server-rendered PDF (see lib/invoice-pdf.ts).
13	 *
14	 * This is the download counterpart of the HTML route in `../route.ts`; it mirrors
15	 * that route's guards EXACTLY — authenticated, and the caller must own the invoice
16	 * or be an admin — so the PDF is never a way to read another customer's billing.
17	 */
18	export async function GET(_req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
19	  const { id } = await params;
20	  const user = await currentUser();
21	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
22	
23	  const invoice = await db.invoice.findUnique({
24	    where: { id },
25	    include: { user: { select: { name: true, email: true } } },
26	  });
27	  if (!invoice) return NextResponse.json({ error: "not found" }, { status: 404 });
28	
29	  const isOwner = invoice.userId === user.id;
30	  const isAdmin = user.role === "ADMIN";
31	  if (!isOwner && !isAdmin) {
32	    return NextResponse.json({ error: "forbidden" }, { status: 403 });
33	  }
34	
35	  const branding = await invoiceBranding();
36	  const pdf = await renderInvoicePDF(invoice, invoice.user, branding);
37	  const filename = invoicePdfFilename(invoice.number, branding.numberPrefix);
