1	import { NextRequest, NextResponse } from "next/server";
2	import { consumeVerificationToken } from "@/lib/email-verification";
3	
4	/**
5	 * The target of the link in the verification email.
6	 *
7	 * A route handler rather than a page because redeeming a token is a WRITE, and a
8	 * write during a server component's render is a bug waiting to happen — React
9	 * may render a component more than once, and Next may prefetch it. Handlers run
10	 * exactly once per request. The outcome is then shown by /verify-email, which
11	 * renders and mutates nothing.
12	 *
13	 * `GET` is correct here despite being a mutation: the customer arrives by
14	 * clicking a link in mail, and the "unsafe method" objection does not apply
15	 * because the token IS the intent and it is single-use. Mail security scanners
16	 * that pre-fetch links will consume the token — which is why
17	 * `consumeVerificationToken` reports an already-verified account as a success
18	 * rather than an error. A scanner that can read the link is inside the
19	 * recipient's own mail infrastructure, so it fetching the link is evidence of
20	 * exactly the control we are testing for, not a bypass of it.
21	 */
22	export async function GET(req: NextRequest) {
23	  const token = req.nextUrl.searchParams.get("token") ?? "";
24	  let status: string;
25	  try {
26	    status = await consumeVerificationToken(token);
27	  } catch (e) {
28	    console.error("[verify-email] failed to consume token:", e);
29	    status = "error";
30	  }
31	  const dest = new URL("/verify-email", req.nextUrl.origin);
32	  dest.searchParams.set("status", status);
33	  return NextResponse.redirect(dest, { status: 303 });
34	}
