1	/**
2	 * One-click MARKETING unsubscribe — tokenized, no-login.
3	 *
4	 * A signed (HMAC-SHA256) token identifies the user and carries a fixed PURPOSE
5	 * tag so it can never be repurposed as any other kind of link. The signing key is
6	 * the platform's existing `AUTH_SECRET` (the same secret lib/crypto-box.ts and
7	 * lib/auth.ts derive from) — no new unmanaged secret is introduced.
8	 *
9	 * `optOutMarketing` writes the EXACT signal `mayDeliverTo(userId,'product_news',
10	 * 'email')` reads: `User.notificationPrefs.product = false` (PRODUCT tier →
11	 * `mayDeliver` returns `prefs.product`). It also drops the address from the
12	 * newsletter list, mirroring `updateNotificationPrefs` so a marketing-consent
13	 * withdrawal is honoured everywhere marketing is addressed.
14	 */
15	import { createHmac, timingSafeEqual } from "node:crypto";
16	import { db } from "./db";
17	import { appUrl } from "./email-render";
18	import { normalizePrefs } from "./prefs";
19	
20	/** Baked into the signature so a token minted here can only ever unsubscribe. */
21	const PURPOSE = "unsub-marketing";
22	
23	function signingSecret(): string {
24	  const s = process.env.AUTH_SECRET;
25	  if (!s) throw new Error("AUTH_SECRET is not set — cannot sign unsubscribe tokens");
26	  return s;
27	}
28	
29	function sign(userId: string): string {
30	  return createHmac("sha256", signingSecret()).update(`${PURPOSE}:${userId}`).digest("base64url");
31	}
32	
33	/** `<userId>.<hmac>` — cuid userIds contain no dot, so the split is unambiguous. */
34	export function marketingUnsubToken(userId: string): string {
35	  return `${userId}.${sign(userId)}`;
36	}
37	
38	/** Verify a token and return its userId, or null if malformed / bad signature. */
39	export function verifyMarketingUnsubToken(token: string | null | undefined): string | null {
40	  if (!token) return null;
41	  const dot = token.lastIndexOf(".");
42	  if (dot <= 0 || dot >= token.length - 1) return null;
43	  const userId = token.slice(0, dot);
44	  const sig = token.slice(dot + 1);
45	  let expected: string;
46	  try {
47	    expected = sign(userId);
48	  } catch {
49	    return null;
50	  }
51	  const a = Buffer.from(sig);
52	  const b = Buffer.from(expected);
53	  if (a.length !== b.length) return null;
54	  return timingSafeEqual(a, b) ? userId : null;
55	}
56	
57	/** The absolute one-click unsubscribe URL for a user (used in the email + header). */
58	export function marketingUnsubUrl(userId: string): string {
59	  return `${appUrl()}/api/unsubscribe?token=${encodeURIComponent(marketingUnsubToken(userId))}`;
60	}
61	
62	/**
63	 * Opt a user OUT of marketing / product-news. IDEMPOTENT.
64	 *
65	 * Returns true when the user exists (whether or not a change was needed), false
66	 * when the userId resolves to no account.
67	 */
68	export async function optOutMarketing(userId: string): Promise<boolean> {
69	  const user = await db.user.findUnique({
70	    where: { id: userId },
71	    select: { email: true, notificationPrefs: true },
72	  });
73	  if (!user) return false;
74	
75	  const prefs = normalizePrefs(user.notificationPrefs);
76	  if (prefs.product) {
77	    // security stays pinned true (see NotificationPrefs.security).
78	    await db.user.update({
79	      where: { id: userId },
80	      data: { notificationPrefs: { email: prefs.email, product: false, security: true } },
81	    });
82	  }
83	  // Mirror updateNotificationPrefs: campaigns are addressed BY EMAIL, so also drop
84	  // the address from the product-news list. Best-effort — never block the opt-out.
85	  try {
86	    await db.newsletterSubscriber.deleteMany({ where: { email: user.email.toLowerCase() } });
87	  } catch {
88	    /* table optional on some environments */
89	  }
90	  return true;
91	}
